CREATE COLUMN TABLE "TEST_AP"."OCFP" ("ID" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(6) NOT NULL , "Descrip" NCLOB MEMORY THRESHOLD 1000, "App" NCLOB MEMORY THRESHOLD 1000, "Locked" NVARCHAR(1) DEFAULT 'N', "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" NVARCHAR(6), "LogInstanc" INTEGER CS_INT, "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, PRIMARY KEY ("ID")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OCFP_CFOP_CODE" ON "TEST_AP"."OCFP" ( "Code" ASC )